const PMWH3_CONFIRM_DELETE='<?= !empty($pmwh3ConfirmDelete) ? "true" : "false"; ?>',PMWH3_CONFIRM_CHANGES='<?= !empty($pmwh3ConfirmChanges) ? "true" : "false"; ?>';
function setSidebarState(d){const a=document.querySelector(".sidebar"),e=document.querySelectorAll(".pmwh3-content"),c=document.querySelector(".openbtn");null!==c&&(d?(a.style.width="250px",e.forEach(b=>b.style.marginLeft="250px"),c.style.left="135px",localStorage.setItem("sidebar","open")):(a.style.width="0",e.forEach(b=>b.style.marginLeft="0"),c.style.left="0",localStorage.setItem("sidebar","closed")))}
function toggleNav(){const d=document.querySelector(".sidebar");"0px"===window.getComputedStyle(d).width?setSidebarState(!0):setSidebarState(!1)}
function pmwh3_bindConfirm(d){d.querySelectorAll("[data-confirm]").forEach(a=>{const e=a.getAttribute("data-confirm");if("change"===(a.getAttribute("data-confirm-type")||"delete")?"true"===PMWH3_CONFIRM_CHANGES:"true"===PMWH3_CONFIRM_DELETE){var c=a.tagName.toLowerCase();"form"===c?a.addEventListener("submit",function(b){confirm(e)||b.preventDefault()}):("a"===c||"button"===c)&&a.addEventListener("click",function(b){confirm(e)||(b.preventDefault(),b.stopImmediatePropagation())})}})}
document.addEventListener("DOMContentLoaded",()=>{"closed"===localStorage.getItem("sidebar")?setSidebarState(!1):setSidebarState(!0);pmwh3_bindConfirm(document)});
